#include "opt/sfm/sfmNtk.c"
#include "opt/sfm/sfmWin.c"
static void row(Vec_Int_t *v){for(int i=0;i<v->nSize;i++)printf("%d,",v->pArray[i]);printf("|");}
int main(void){int ni,nn,no,target,tfo,fanout,cap,growth;while(scanf("%d%d%d%d%d%d%d%d",&ni,&nn,&no,&target,&tfo,&fanout,&cap,&growth)==8){Sfm_Ntk_t p={0};Sfm_Par_t pars={0};int n=ni+nn+no;p.nPis=ni;p.nPos=no;p.nObjs=n;p.pPars=&pars;pars.nTfoLevMax=tfo;pars.nFanoutMax=fanout;pars.nWinSizeMax=cap;pars.nGrowthLevel=growth;p.vFixed=Vec_StrStart(n);p.vEmpty=Vec_StrStart(n);Vec_WecInit(&p.vFanins,n);for(int id=0;id<n;id++){int count,fixed,empty;scanf("%d%d%d",&count,&fixed,&empty);Vec_StrWriteEntry(p.vFixed,id,fixed);Vec_StrWriteEntry(p.vEmpty,id,empty);for(int k=0;k<count;k++){int f;scanf("%d",&f);Vec_IntPush(Vec_WecEntry(&p.vFanins,id),f);}}
Sfm_CreateFanout(&p.vFanins,&p.vFanouts);Sfm_CreateLevel(&p.vFanins,&p.vLevels,p.vEmpty);Sfm_CreateLevelR(&p.vFanouts,&p.vLevelsR,p.vEmpty);p.nLevelMax=Vec_IntFindMax(&p.vLevels)+growth;Vec_IntFill(&p.vTravIds,n,0);Vec_IntFill(&p.vTravIds2,n,0);Vec_IntFill(&p.vCounts,n,0);p.vNodes=Vec_IntAlloc(0);p.vDivs=Vec_IntAlloc(0);p.vRoots=Vec_IntAlloc(0);p.vTfo=Vec_IntAlloc(0);p.vOrder=Vec_IntAlloc(0);int mffc=Sfm_ObjMffcSize(&p,target);int ok=Sfm_NtkCreateWindow(&p,target,0);printf("%d %d ",ok,mffc);row(&p.vLevels);row(&p.vLevelsR);row(p.vNodes);row(p.vDivs);row(p.vRoots);row(p.vTfo);row(p.vOrder);puts("");
Vec_StrFree(p.vFixed);Vec_StrFree(p.vEmpty);Vec_WecErase(&p.vFanins);Vec_WecErase(&p.vFanouts);Vec_IntErase(&p.vLevels);Vec_IntErase(&p.vLevelsR);Vec_IntErase(&p.vTravIds);Vec_IntErase(&p.vTravIds2);Vec_IntErase(&p.vCounts);Vec_IntFree(p.vNodes);Vec_IntFree(p.vDivs);Vec_IntFree(p.vRoots);Vec_IntFree(p.vTfo);Vec_IntFree(p.vOrder);
}return 0;}
